import os
import sys
import subprocess
import tabulate
from pathlib import Path

def process_job(job_name, command):
    try:
        result = subprocess.run(
            command,
            shell=True,
            check=False,
            text=True,
            capture_output=True,
            encoding='utf-8',
            errors='replace'
        )
        return job_name, command, result.returncode, result.stdout + result.stderr
    except Exception:
        return job_name, command, -1, ""

def escape_output(output):
    if not output:
        return ""
    escaped = []
    for char in output:
        if char == '\\':
            escaped.append('\\\\')
        elif char == '\n':
            escaped.append('\\n')
        elif char == '\t':
            escaped.append('\\t')
        elif char == '\r':
            escaped.append('\\r')
        else:
            escaped.append(char)
    return ''.join(escaped)

def load_results():
    if not Path('bulkrun_results.tsv').exists():
        return []
    with open('bulkrun_results.tsv', 'r', encoding='utf-8') as f:
        return [line.strip().split('\t') for line in f if line.strip()]

def save_results(results):
    with open('bulkrun_results.tsv', 'w', encoding='utf-8') as f:
        for job in results:
            f.write('\t'.join(job) + '\n')

def main():
    if len(sys.argv) != 2:
        print("Usage: python bulkrun.py <jobs_file>", file=sys.stderr)
        sys.exit(1)

    jobs_file = sys.argv[1]
    results = load_results()
    executed = 0
    skipped = 0

    with open(jobs_file, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line or '\t' not in line:
                continue
            job_name, command = line.split('\t', 1)
            if job_name in [r[0] for r in results if r[1] == command and r[2] == '0']:
                skipped += 1
                continue

            job_name, command, status, output = process_job(job_name, command)
            escaped_output = escape_output(output)
            results.append([job_name, command, str(status), escaped_output])
            executed += 1

    save_results(results)
    print(f"executed={executed} skipped={skipped}")

if __name__ == "__main__":
    main()

import os
import sys
import subprocess
import argparse
from typing import List, Tuple, Dict, Optional

def escape_output(output: str) -> str:
    escaped = []
    for char in output:
        if char == '\\':
            escaped.append('\\\\')
        elif char == '\n':
            escaped.append('\\n')
        elif char == '\t':
            escaped.append('\\t')
        elif char == '\r':
            escaped.append('\\r')
        else:
            escaped.append(char)
    return ''.join(escaped)

def load_results() -> List[Tuple[str, str, int, str]]:
    if not os.path.exists('bulkrun_results.tsv'):
        return []
    with open('bulkrun_results.tsv', 'r', encoding='utf-8') as f:
        return [
            tuple(line.strip().split('\t'))
            for line in f
            if line.strip()
        ]

def save_results(results: List[Tuple[str, str, int, str]]) -> None:
    with open('bulkrun_results.tsv', 'w', encoding='utf-8') as f:
        for job_name, cmd, status, output in results:
            escaped_output = escape_output(output)
            f.write(f"{job_name}\t{cmd}\t{status}\t{escaped_output}\n")

def process_job(job_name: str, cmd: str, existing_results: List[Tuple[str, str, int, str]]) -> Tuple[bool, str]:
    for existing in existing_results:
        if existing[0] == job_name and existing[2] == 0:
            return (True, "")
    return (False, cmd)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('jobs_file')
    args = parser.parse_args()

    with open(args.jobs_file, 'r', encoding='utf-8') as f:
        jobs = [
            line.strip().split('\t')
            for line in f
            if line.strip()
            and len(line.strip().split('\t')) == 2
        ]

    existing_results = load_results()
    executed_jobs = []
    skipped_jobs = []

    for job_name, cmd in jobs:
        if not cmd:
            continue
        skip, _ = process_job(job_name, cmd, existing_results)
        if skip:
            skipped_jobs.append(job_name)
            continue

        try:
            result = subprocess.run(
                cmd,
                shell=True,
                check=False,
                text=True,
                capture_output=True,
                encoding='utf-8',
                errors='replace'
            )
            escaped_output = escape_output(result.stdout + result.stderr)
            executed_jobs.append((job_name, cmd, result.returncode, escaped_output))
        except Exception:
            executed_jobs.append((job_name, cmd, -1, ""))  # Handle unexpected errors

    save_results(executed_jobs + existing_results)
    print(f"executed={len(executed_jobs)} skipped={len(skipped_jobs)}")

if __name__ == "__main__":
    main()
